bounded_host_request.command:
set -e
f="$HOME/Project/Gserver/projects/TGtumbler/GateApp-Bot/scripts/userbot_test_client.py"
test -f "$f"
python3 - "$f" <<'PY'
import ast,sys
t=ast.parse(open(sys.argv[1],encoding="utf8").read())
for n in ast.walk(t):
 if isinstance(n,ast.Assign) and any(isinstance(x,ast.Name) and x.id=='ACTIONS' for x in n.targets):
  try:print('USERBOT_ALLOWED_ACTIONS='+','.join(sorted(ast.literal_eval(n.value))))
  except Exception:print('USERBOT_ACTION_SET_DYNAMIC')
 if isinstance(n,ast.Assign) and any(isinstance(x,ast.Name) and x.id=='SOCKET_PATH' for x in n.targets):
  print('USERBOT_SOCKET_DEFINED=YES')
PY
printf 'USERBOT_SERVICE_ACTIVE='
systemctl --user is-active gace-userbot-verify.service
echo USERBOT_INTERFACE_DISCOVERED=PASS
